query.base:
TS metrics-gcp.cloudsql_postgresql.otel-*
| WHERE gcp.resource_type == "cloudsql_database"
// Resolve per minute first: series fragmentation means one logical series can be
// split across many TSDB series, so never use MAX(LAST_OVER_TIME()) for the latest value.
| STATS state_flag = MAX(MAX_OVER_TIME(`cloudsql.googleapis.com/database/instance_state`)),
        up = MAX(MAX_OVER_TIME(`cloudsql.googleapis.com/database/up`)),
        pg = SUM(COUNT_OVER_TIME(`cloudsql.googleapis.com/database/postgresql/num_backends`))
    BY `@timestamp` = TBUCKET(1 minute), database_id, attributes.state
// PostgreSQL engine marker, evaluated over the whole rule window (24h) so that an
// instance that has just stopped (and no longer emits num_backends) stays in scope.
| INLINE STATS pg_total = SUM(pg) BY database_id
// Signal window: only the most recent minutes decide the current state.
// Keep this >= 10-15 minutes to tolerate the 3-5+ minute Cloud Monitoring ingestion delay.
| WHERE pg_total > 0 AND `@timestamp` >= NOW() - 15 minutes
// attributes.state is only meaningful on instance_state rows whose value is 1
| EVAL current_state = CASE(state_flag == 1, attributes.state, NULL),
       state_ts = CASE(state_flag == 1, `@timestamp`, NULL),
       up_ts = CASE(up IS NOT NULL, `@timestamp`, NULL)
| STATS state = LAST(current_state, state_ts),
        up = LAST(up, up_ts),
        last_seen = MAX(`@timestamp`)
    BY database_id

breach.segment:
WHERE up IS NOT NULL OR state IS NOT NULL
// Breach: the instance is not serving (up = 0) or is in a non-RUNNING state.
// MAINTENANCE is Google-scheduled and expected; it only alerts if it outlasts the
// alert delay. If owners intentionally stop instances (RUNNABLE) or you want to ignore
// maintenance, append e.g. | WHERE COALESCE(state, "") NOT IN ("RUNNABLE", "MAINTENANCE")
| WHERE up == 0 OR (state IS NOT NULL AND state != "RUNNING")
| EVAL reason = CASE(
    state IS NOT NULL AND state != "RUNNING", CONCAT("instance_state=", state),
    "up=0 (not serving while RUNNING)")
| KEEP database_id, state, up, reason, last_seen
| SORT database_id
| LIMIT 100
